use xiom.io;

use xiom.string;
fn main() -> Int {
  let score = Some(88);
  let name: Option[Str] = None;

  let result = match score {
    Some(s) => "Passed: " + to_string(s),
    None => "No score",
  };

  io.println(result.to_str());
  return 0;
}
